SELECT $this
WHERE {
    FILTER NOT EXISTS {
        $this rdf:type ?admittedType .
        ?admittedType rdfs:subClassOf* nltl:ship .
    }
}

SELECT $this
WHERE {
    $this nltl:upperIceWaterlineDisplacement ?upperQuantity .
    ?upperQuantity qudt:numericValue ?upperValue ;
                    qudt:unit unit:KiloTON_Metric .

    FILTER EXISTS {
        $this nltl:hasUpperIceWaterlineCase ?case .
        ?case nltl:waterlineCaseDisplacement ?caseQuantity .
        ?caseQuantity qudt:numericValue ?caseValue ;
                      qudt:unit unit:KiloTON_Metric .
        FILTER (?caseValue > ?upperValue)
    }
}

sh:sparql [
    a sh:SPARQLConstraint ;
    sh:select """
        SELECT $this
        WHERE {
            $this nltl:upperIceWaterlineDisplacement ?upperQuantity .
            ?upperQuantity qudt:numericValue ?upperValue ;
                            qudt:unit unit:KiloTON_Metric .

            FILTER EXISTS {
                $this nltl:hasUpperIceWaterlineCase ?case .
                ?case nltl:waterlineCaseDisplacement ?caseQuantity .
                ?caseQuantity qudt:numericValue ?caseValue ;
                              qudt:unit unit:KiloTON_Metric .
                FILTER (?caseValue > ?upperValue)
            }
        }
